class Shortcut {
 public uint Modifiers=1,Code;
 public Shortcut(){}
 public Shortcut(uint code){Code=code;}
 public Shortcut Copy(){return new Shortcut{Modifiers=Modifiers,Code=Code};}
 public long Identity(){return ((long)Modifiers<<32)|Code;}
}
class Settings {
 public string Url="https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",Model="qwen3.8-flash",Secret="",Language="简体中文";
 public RecordingSettings Recording=new RecordingSettings();public string ScreenshotDirectory=ShotStore.DefaultDirectory;public bool CompletionSound=true;public MailSettings Mail=new MailSettings();
 public Shortcut[] Shortcuts=Defaults();
 public static string Dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"config");
 public static Shortcut[] Defaults(){return new[]{new Shortcut(0x33),new Shortcut(0x34),new Shortcut(0x35),new Shortcut(0x36),new Shortcut(0x37),new Shortcut(0x38),new Shortcut(0x32),new Shortcut(0x39),new Shortcut(0x31),new Shortcut(0xC0)};}
 public static Settings Load(){try{var value=new JavaScriptSerializer().Deserialize<Settings>(File.ReadAllText(Path.Combine(Dir,"settings.json")))??new Settings();var defaults=Defaults();if(value.Shortcuts==null)value.Shortcuts=defaults;else if(value.Shortcuts.Length!=defaults.Length){var previous=value.Shortcuts;value.Shortcuts=defaults;for(int i=0;i<Math.Min(previous.Length,defaults.Length);i++)if(previous[i]!=null)value.Shortcuts[i]=previous[i];var used=new HashSet<long>();for(int i=0;i<defaults.Length;i++){if(value.Shortcuts[i]==null)value.Shortcuts[i]=Defaults()[i];if(!used.Add(value.Shortcuts[i].Identity())){foreach(uint code in new uint[]{0xC0,0x36,0x37,0x38,0x39,0x75,0x76}){var candidate=new Shortcut{Modifiers=3,Code=code};if(used.Add(candidate.Identity())){value.Shortcuts[i]=candidate;break;}}}}}for(int i=0;i<value.Shortcuts.Length;i++)if(value.Shortcuts[i]==null)value.Shortcuts[i]=Defaults()[i];if(string.IsNullOrWhiteSpace(value.ScreenshotDirectory))value.ScreenshotDirectory=ShotStore.DefaultDirectory;if(value.Recording==null)value.Recording=new RecordingSettings();if(value.Mail==null)value.Mail=new MailSettings();if(string.IsNullOrWhiteSpace(value.Language))value.Language="简体中文";return value;}catch{return new Settings();}}
 public string Key(){try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(Secret),null,DataProtectionScope.CurrentUser));}catch{return "";}}
 public Settings Copy(){var copy=new Settings{Url=Url,Model=Model,Secret=Secret,Language=Language,CompletionSound=CompletionSound,Mail=Mail.Copy(),ScreenshotDirectory=ScreenshotDirectory,Recording=Recording.Copy()};for(int i=0;i<Mode.All.Length;i++)copy.Shortcuts[i]=Shortcuts[i].Copy();return copy;}
 public void Save(string key){Secret=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(key),null,DataProtectionScope.CurrentUser));Directory.CreateDirectory(Dir);string target=Path.Combine(Dir,"settings.json"),temp=target+".new";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(this));if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}
}
class Mode {
