 new Mode{Index=2,Title="名词解释",Description="结合截图语境，解释术语并给出示例",ResultTitle="名词解释",Color=Color.FromArgb(170,112,40)},
 new Mode{Index=3,Title="截图总结",Description="提炼主要内容，整理成简洁要点",ResultTitle="内容总结",Color=Color.FromArgb(118,89,165)},
