 public ResultWindow(Mode mode,string language,Action repeat){Mode=mode;SuspendLayout();Text=mode.ResultTitle+" · AI截图助手";Icon=Theme.Icon();FormBorderStyle=FormBorderStyle.None;ClientSize=new Size(680,480);MinimumSize=new Size(590,400);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.White;Font=new Font("Microsoft YaHei UI",9);content=new RichTextBox();table=new DataGridView{AllowUserToAddRows=false};modern=new ModernResultView(this,mode,language);new ResultEscapeFilter(this,modern.Root);modern.Copy=async()=>{try{await Theme.CopyText(Output);if(!IsDisposed)modern.Note("已复制到剪贴板");}catch(Exception e){if(!IsDisposed)modern.Note("复制失败："+e.Message);}};modern.Export=()=>Export();modern.OpenUrl=()=>{Uri uri;if(!QrDecoder.WebUrl(Output,out uri))return;try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}catch(Exception e){modern.Note("打开失败："+e.Message);}};modern.Retry=()=>{bool rerun=Complete||failed;Close();if(rerun)repeat();};Controls.Add(ModernChrome.Host(modern.Root));FormClosed+=(sender,args)=>Cancellation.Cancel();Shown+=(sender,args)=>ModernChrome.Round(this);KeyPreview=true;KeyDown+=(sender,args)=>{if(args.KeyCode==Keys.Escape)Close();};AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;ResumeLayout(true);}
