 public void Failure(string error){if(IsDisposed)return;failed=true;modern.Failure(error);}
 void Export(){using(var dialog=new SaveFileDialog{Title="导出"+Mode.ResultTitle,Filter=Mode.Index==4?"TSV 表格|*.tsv":"文本文件|*.txt",FileName=Mode.Title+(Mode.Index==4?".tsv":".txt"),InitialDirectory=AppDomain.CurrentDomain.BaseDirectory}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{File.WriteAllText(dialog.FileName,Output,new UTF8Encoding(true));modern.Note("已导出");}catch(Exception e){modern.Note("导出失败："+e.Message);}}}
}
