 url=new TextBox{Text=config.Url};model=new TextBox{Text=config.Model};key=new TextBox{Text=config.Key()};language=new ComboBox{Text=config.Language};sound=new CheckBox{Checked=config.CompletionSound};status=new Label{Text="就绪"};save=Theme.Button("保存设置",true);for(int i=0;i<Mode.All.Length;i++){inputs[i]=new HotkeyInput{Modifiers=config.Shortcuts[i].Modifiers,Code=config.Shortcuts[i].Code};inputs[i].RefreshText();runButtons[i]=Theme.Button("框选",false);}
