 void Status(string text){if(IsDisposed)return;if(IsHandleCreated&&InvokeRequired){BeginInvoke(new Action(()=>Status(text)));return;}if(status!=null)status.Text=text;if(modern!=null)modern.Status(text);if(tray!=null)tray.Text=text.Length>60?text.Substring(0,60):text;}
