 bool Save(){Uri address;if(!Uri.TryCreate(url.Text.Trim(),UriKind.Absolute,out address)||(address.Scheme!="http"&&address.Scheme!="https")){Status("请输入有效的 HTTP 或 HTTPS API 地址");return false;}if(string.IsNullOrWhiteSpace(model.Text)||string.IsNullOrWhiteSpace(language.Text)){Status("请填写模型名和翻译目标语言");return false;}var updated=config.Copy();try{updated.ScreenshotDirectory=ShotStore.DirectoryPath(modern.ReadShotDirectory());Directory.CreateDirectory(updated.ScreenshotDirectory);}catch(Exception e){Status("截图目录："+e.Message);modern.Page(4);return false;}try{updated.Mail=modern.ReadMail();if(updated.Mail.Configured())updated.Mail.Validate();}catch(Exception e){Status("邮件设置："+e.Message);modern.Page(3);return false;}updated.Url=url.Text.Trim();updated.Model=model.Text.Trim();updated.Language=language.Text.Trim();updated.CompletionSound=sound.Checked;for(int i=0;i<Mode.All.Length;i++)updated.Shortcuts[i]=new Shortcut{Modifiers=inputs[i].Modifiers,Code=inputs[i].Code};string error;if(hotkeys==null){Status("快捷键尚未初始化");return false;}if(!hotkeys.TryApply(updated.Shortcuts,out error)){Status(error);return false;}try{bool oldStartup=StartupRegistration.IsEnabled();StartupRegistration.SetEnabled(startupEnabled);try{updated.Save(key.Text.Trim());}catch{StartupRegistration.SetEnabled(oldStartup);throw;}config=updated;modern.UpdateShotHelp(config.Shortcuts);for(int i=0;i<Mode.All.Length;i++)trayActions[i].Text=Mode.All[i].Title+"  "+HotkeyInput.Format(config.Shortcuts[i].Modifiers,config.Shortcuts[i].Code);Status("已保存 · 快捷键立即生效");return true;}catch(Exception e){hotkeys.TryApply(config.Shortcuts,out error);Status("保存失败："+e.Message);return false;}}
 bool Ready(){if(string.IsNullOrWhiteSpace(config.Model)||string.IsNullOrWhiteSpace(config.Key())){Status("请先在连接设置中填写模型和 API Key，再保存");Open();ShowPage(true);return false;}return true;}
 async Task RunMode(int index){if(index==9){if(!busy)await StartRecordingFlow(null);return;}if(index==8){await RunShot();return;}if(index==7){await SendScreenMail();return;}if(busy||(index!=5&&index!=6&&!Ready()))return;busy=true;foreach(var button in runButtons)button.Enabled=false;save.Enabled=false;if(modern!=null)modern.Busy(true);bool wasVisible=Visible;Hide();try{while((GetAsyncKeyState(0x12)&0x8000)!=0||(GetAsyncKeyState(0x11)&0x8000)!=0||(GetAsyncKeyState(0x10)&0x8000)!=0||(GetAsyncKeyState((int)config.Shortcuts[index].Code)&0x8000)!=0)await Task.Delay(20);await Task.Delay(80);Bitmap image;using(var picker=new Capture()){picker.ShowDialog();image=picker.Result;}if(image==null){Status("已取消框选");if(wasVisible)Open();return;}string data;using(image){ShotStore.SaveNew(image,config.ScreenshotDirectory);if(index==5||index==6){using(var stream=new MemoryStream()){image.Save(stream,ImageFormat.Png);data="data:image/png;base64,"+Convert.ToBase64String(stream.ToArray());}}else data=ScreenshotImage.Encode(image);}await ProcessImage(index,data);}catch(Exception e){Status("操作失败："+e.Message);}finally{busy=false;if(!IsDisposed){foreach(var button in runButtons)button.Enabled=true;save.Enabled=true;if(modern!=null)modern.Busy(false);}}}
 async Task<bool> ProcessImage(int index,string image){return await ProcessImageCore(index,image,false,null);}
 async Task<bool> ProcessImageCore(int index,string image,bool smart,string local){
 if(index==6){Status("智能识别 · 正在判断用途…");int chosen;string decoded=null;using(var cancellation=new CancellationTokenSource()){runningCancellation=cancellation;try{try{decoded=await Task.Run(()=>QrDecoder.DecodeImage(image),cancellation.Token);}catch(Exception){cancellation.Token.ThrowIfCancellationRequested();}if(decoded!=null)chosen=5;else{if(!Ready())return false;chosen=SmartIntent.Parse(await ModelClient.Request(config.Copy(),Mode.All[6],image,cancellation.Token,false,null));}}catch(Exception e){Status("智能识别失败："+e.Message);return false;}finally{runningCancellation=null;}}return await ProcessImageCore(chosen,image,true,decoded);}
var request=config.Copy();var mode=Mode.All[index];ResultWindow popup=null;string failure=null;bool success=false;var elapsed=System.Diagnostics.Stopwatch.StartNew();runningCancellation=new CancellationTokenSource();if(index!=0)await Ui(()=>{popup=new ResultWindow(mode,request.Language,()=>BeginInvoke(new Action(async()=>await RunMode(index))));popup.FormClosed+=(sender,args)=>dialogs.Remove(popup);dialogs.Add(popup);if(smart)popup.EnableSmartSwitch(next=>{if(busy){Status("当前操作尚未完成，请稍后切换");return;}popup.Close();BeginInvoke(new Action(async()=>{busy=true;modern.Busy(true);try{await ProcessImageCore(next,image,true,null);}finally{busy=false;modern.Busy(false);}}));});popup.Show();popup.Activate();});var cancel=popup==null?runningCancellation:popup.Cancellation;try{Status("正在"+mode.Title+"…");string output=local??(index==5?await Task.Run(()=>QrDecoder.DecodeImage(image),cancel.Token):await ModelClient.Request(request,mode,image,cancel.Token,false,popup==null?(Action<string>)null:partial=>QueuePartial(popup,partial)));cancel.Token.ThrowIfCancellationRequested();if(index==0){await Theme.CopyText(output);cancel.Token.ThrowIfCancellationRequested();await Ui(()=>CopyToast.ShowCopied());Status("文字已复制 · "+elapsed.Elapsed.TotalSeconds.ToString("0.0")+" 秒");}else{await Ui(()=>{if(!popup.IsDisposed)popup.Success(output);});Status(mode.Title+"完成 · "+elapsed.Elapsed.TotalSeconds.ToString("0.0")+" 秒");}cancel.Token.ThrowIfCancellationRequested();if(request.CompletionSound)CompletionTone.Play();success=true;}catch(OperationCanceledException){Status("已取消"+mode.Title);}catch(Exception e){failure=e.Message;Status(mode.Title+"失败："+e.Message);}finally{if(runningCancellation!=null)runningCancellation.Dispose();runningCancellation=null;}if(failure!=null&&popup!=null)await UiAfterError(popup,failure);return success;}
 async Task SendScreenMail(){if(busy)return;try{config.Mail.Validate();}catch(Exception e){Status("邮件未就绪："+e.Message);Open();modern.Page(3);return;}busy=true;modern.Busy(true);var mail=config.Mail.Copy();bool visible=Visible;try{while((GetAsyncKeyState(0x12)&0x8000)!=0||(GetAsyncKeyState((int)config.Shortcuts[7].Code)&0x8000)!=0)await Task.Delay(20);Hide();await Task.Delay(180);byte[] image=ScreenshotMail.CaptureFullScreen();using(var stream=new MemoryStream(image))using(var bitmap=new Bitmap(stream))ShotStore.SaveNew(bitmap,config.ScreenshotDirectory);Status("正在发送全屏截图…");await Task.Run(()=>ScreenshotMail.Send(mail,image));Status("邮件已发送 · "+mail.Recipients().Length+" 位收件人");CopyToast.ShowMessage("邮件已发送");if(config.CompletionSound)CompletionTone.Play();}catch(Exception){Status("邮件发送失败，请检查 SMTP 配置、授权码和收件人；未自动重试");CopyToast.ShowMessage("邮件发送失败");}finally{busy=false;modern.Busy(false);if(visible)Open();}}
 void TrackShot(Form form){shotWindows.Add(form);form.FormClosed+=(s,e)=>shotWindows.Remove(form);}
 void OpenShotHistory(){try{var list=ShotStore.History(config.ScreenshotDirectory);if(list.Count==0){Status("还没有截图，按 F8 开始截图");return;}var editor=new ShotEditor(config.ScreenshotDirectory,list[list.Count-1]);editor.Track=TrackShot;TrackShot(editor);editor.Show();}catch(Exception e){Status("打开截图失败："+e.Message);}}
 async Task RunShot(){if(busy)return;busy=true;modern.Busy(true);bool visible=Visible;Hide();try{while((GetAsyncKeyState((int)config.Shortcuts[8].Code)&0x8000)!=0||(GetAsyncKeyState(0x12)&0x8000)!=0||(GetAsyncKeyState(0x11)&0x8000)!=0||(GetAsyncKeyState(0x10)&0x8000)!=0)await Task.Delay(20);await Task.Delay(80);using(var picker=new InlineShot(config.ScreenshotDirectory)){picker.ShowDialog();if(picker.RecordingBounds.HasValue){await StartRecordingFlow(picker.RecordingBounds);return;}if(picker.PinPath!=null){var pin=new ShotPin(config.ScreenshotDirectory,picker.PinPath);pin.Track=TrackShot;TrackShot(pin);pin.Show();}if(picker.RequestedMode>=0&&picker.RequestedImage!=null){if(picker.RequestedMode==5||picker.RequestedMode==6||Ready())await ProcessImage(picker.RequestedMode,picker.RequestedImage);}else Status(picker.Captured?"截图已保存":"已取消截图");}}catch(Exception e){Status("截图失败："+e.Message);if(visible)Open();}finally{busy=false;modern.Busy(false);}}
 async Task StartRecordingFlow(Rectangle? selected){if(recordingPanel!=null&&!recordingPanel.IsDisposed){if(!recordingPanel.Completed){recordingPanel.Show();recordingPanel.Activate();Status("录屏已在进行中");return;}recordingPanel.Close();}bool priorBusy=busy;busy=true;modern.Busy(true);try{RecordingSettings options;using(var dialog=new RecordingOptionsForm(config.Recording,selected)){if(dialog.ShowDialog()!=DialogResult.OK)return;options=dialog.Selected;}Hide();Rectangle region;if(options.FullScreen)region=SystemInformation.VirtualScreen;else if(selected.HasValue)region=selected.Value;else{await Task.Delay(150);using(var picker=new Capture()){picker.ShowDialog();if(picker.Result==null){Status("已取消录屏框选");return;}region=picker.SelectedScreenBounds;picker.Result.Dispose();}}config.Recording=options.Copy();config.Save(config.Key());recordingPanel=new RecordingControl(options,region);recordingPanel.Report=Status;TrackShot(recordingPanel);recordingPanel.Show();await recordingPanel.BeginAsync();}catch(Exception e){Status("无法启动录屏："+e.Message);CopyToast.ShowMessage("录屏启动失败");}finally{busy=priorBusy;modern.Busy(priorBusy);}}
 void QueuePartial(ResultWindow popup,string text){if(IsDisposed||popup.IsDisposed)return;try{BeginInvoke(new Action(()=>{if(!popup.IsDisposed)popup.Partial(text);}));}catch(InvalidOperationException){}}
 Task UiAfterError(ResultWindow popup,string error){return Ui(()=>{if(!popup.IsDisposed)popup.Failure(error);});}
 protected override void Dispose(bool disposing){if(disposing){if(runningCancellation!=null)runningCancellation.Cancel();if(hotkeys!=null)hotkeys.Dispose();if(tray!=null)tray.Dispose();foreach(var dialog in dialogs.ToArray())dialog.Close();foreach(var shot in shotWindows.ToArray())shot.Close();}base.Dispose(disposing);}
 [STAThread]static void Main(){bool created;using(var mutex=new Mutex(true,"ScreenText.Tray.Singleton",out created)){if(!created)return;EmbeddedDependencies.Install();EnableDpi();ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var app=new App();if(Array.IndexOf(Environment.GetCommandLineArgs(),"--settings")>=0)app.allowShow=true;if(Array.IndexOf(Environment.GetCommandLineArgs(),"--mail-settings")>=0){app.allowShow=true;app.modern.Page(3);}if(Array.IndexOf(Environment.GetCommandLineArgs(),"--shot-settings")>=0){app.allowShow=true;app.modern.Page(4);}Application.Run(app);}}
