class Capture : Form {
 Bitmap screen; Point start, end; bool dragging;
 public Bitmap Result;public Rectangle SelectedScreenBounds;
 public Capture():this(null,SystemInformation.VirtualScreen){}
 public Capture(Bitmap frozen,Rectangle bounds){AutoScaleMode=AutoScaleMode.None;FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.Manual;Bounds=bounds;TopMost=true;ShowInTaskbar=false;DoubleBuffered=true;Cursor=Cursors.Cross;KeyPreview=true;screen=frozen==null?new Bitmap(bounds.Width,bounds.Height):new Bitmap(frozen);if(frozen==null)using(var g=Graphics.FromImage(screen))g.CopyFromScreen(bounds.Location,Point.Empty,bounds.Size);KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)Close();};MouseDown+=(s,e)=>{if(e.Button!=MouseButtons.Left){Close();return;}start=end=e.Location;dragging=true;base.Capture=true;Invalidate();};MouseMove+=(s,e)=>{if(dragging){end=e.Location;Invalidate();}};MouseUp+=(s,e)=>{if(!dragging)return;end=e.Location;base.Capture=false;var r=Selection();if(r.Width>4&&r.Height>4){SelectedScreenBounds=r;SelectedScreenBounds.Offset(Bounds.Location);Result=screen.Clone(r,PixelFormat.Format24bppRgb);}Close();};}
 Rectangle Selection(){return Rectangle.Intersect(ClientRectangle,Rectangle.FromLTRB(Math.Min(start.X,end.X),Math.Min(start.Y,end.Y),Math.Max(start.X,end.X),Math.Max(start.Y,end.Y)));}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.DrawImageUnscaled(screen,0,0);var r=Selection();using(var dim=new SolidBrush(Color.FromArgb(95,0,0,0)))using(var outside=new Region(ClientRectangle)){if(dragging)outside.Exclude(r);e.Graphics.FillRegion(dim,outside);}if(dragging){using(var p=new Pen(Color.FromArgb(0,135,255),2))e.Graphics.DrawRectangle(p,r);string size=r.Width+" × "+r.Height;var badge=new Rectangle(Math.Max(0,Math.Min(Width-150,r.X)),Math.Max(0,r.Y-32),150,28);using(var background=new SolidBrush(Color.FromArgb(230,25,33,43)))e.Graphics.FillRectangle(background,badge);TextRenderer.DrawText(e.Graphics,size,Font,badge,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}else{var hint=new Rectangle(Math.Max(0,(Width-380)/2),28,380,38);using(var background=new SolidBrush(Color.FromArgb(230,25,33,43)))e.Graphics.FillRectangle(background,hint);TextRenderer.DrawText(e.Graphics,"拖动选择截图区域 · Esc 取消",Font,hint,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}

 protected override void Dispose(bool disposing){if(disposing)screen.Dispose();base.Dispose(disposing);}
}
class SoftPanel : Panel {
 public int Radius=12;public Color BorderColor=Color.Transparent;
 public SoftPanel(){DoubleBuffered=true;SetStyle(ControlStyles.ResizeRedraw,true);}
 protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Parent==null?BackColor:Parent.BackColor);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;float r=Radius*DeviceDpiScale();var rect=new RectangleF(0.5f,0.5f,Width-1,Height-1);using(var path=new System.Drawing.Drawing2D.GraphicsPath()){path.AddArc(rect.X,rect.Y,r*2,r*2,180,90);path.AddArc(rect.Right-r*2,rect.Y,r*2,r*2,270,90);path.AddArc(rect.Right-r*2,rect.Bottom-r*2,r*2,r*2,0,90);path.AddArc(rect.X,rect.Bottom-r*2,r*2,r*2,90,90);path.CloseFigure();using(var brush=new SolidBrush(BackColor))e.Graphics.FillPath(brush,path);if(BorderColor!=Color.Transparent)using(var pen=new Pen(BorderColor))e.Graphics.DrawPath(pen,path);}}
 float DeviceDpiScale(){using(var graphics=CreateGraphics())return graphics.DpiX/96f;}
}

class SoftButton : Button {
 bool hover;
 public SoftButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
