 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Parent==null?Color.White:Parent.BackColor);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;float radius=8*e.Graphics.DpiX/96f;var r=new RectangleF(1,1,Width-2,Height-2);using(var path=new System.Drawing.Drawing2D.GraphicsPath()){path.AddArc(r.X,r.Y,radius*2,radius*2,180,90);path.AddArc(r.Right-radius*2,r.Y,radius*2,radius*2,270,90);path.AddArc(r.Right-radius*2,r.Bottom-radius*2,radius*2,radius*2,0,90);path.AddArc(r.X,r.Bottom-radius*2,radius*2,radius*2,90,90);path.CloseFigure();Color fill=!Enabled?Color.FromArgb(223,231,233):hover?ControlPaint.Light(BackColor,0.12f):BackColor;using(var brush=new SolidBrush(fill))e.Graphics.FillPath(brush,path);if(BackColor==Color.White||Focused)using(var pen=new Pen(Focused?Color.FromArgb(12,121,133):Color.FromArgb(214,224,228)))e.Graphics.DrawPath(pen,path);}TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,Enabled?ForeColor:Color.Gray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine);}
}
class HotkeyInput : TextBox {
 public uint Modifiers=1,Code=0xC0;public event EventHandler ResetRequested;
 public static string Format(uint modifiers,uint code){string text="";if((modifiers&2)!=0)text+="Ctrl + ";if((modifiers&1)!=0)text+="Alt + ";if((modifiers&4)!=0)text+="Shift + ";return text+(code==0xC0?"~":code>=0x30&&code<=0x39?((char)code).ToString():((Keys)code).ToString());}
 public void RefreshText(){Text=Format(Modifiers,Code);SelectionLength=0;}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){Keys code=keyData&Keys.KeyCode;if(code==Keys.Tab)return base.ProcessCmdKey(ref msg,keyData);if(code==Keys.Escape){if(ResetRequested!=null)ResetRequested(this,EventArgs.Empty);Parent.Focus();return true;}if(code==Keys.ControlKey||code==Keys.ShiftKey||code==Keys.Menu||code==Keys.LWin||code==Keys.RWin)return true;uint modifiers=0;if((keyData&Keys.Control)!=0)modifiers|=2;if((keyData&Keys.Alt)!=0)modifiers|=1;if((keyData&Keys.Shift)!=0)modifiers|=4;if((modifiers&3)==0){Text="请加 Ctrl 或 Alt";return true;}Modifiers=modifiers;Code=(uint)code;RefreshText();return true;}
}
